/* Catmull-Rom closed spline -> dense samples + curvature + speed profile */
function buildTrack(tr){
  const P=tr.pts,n=P.length,S=[];
  const N=560;
  for(let i=0;i<N;i++){
    const t=i/N*n, k=Math.floor(t), f=t-k;
    const p0=P[(k-1+n)%n],p1=P[k%n],p2=P[(k+1)%n],p3=P[(k+2)%n];
    const q=(a,b,c,d)=>0.5*((2*b)+(-a+c)*f+(2*a-5*b+4*c-d)*f*f+(-a+3*b-3*c+d)*f*f*f);
    S.push([q(p0[0],p1[0],p2[0],p3[0]),q(p0[1],p1[1],p2[1],p3[1])]);
  }
  // arclength + scale to real km
  let L=0;const seg=[];
  for(let i=0;i<N;i++){const a=S[i],b=S[(i+1)%N];const d=Math.hypot(b[0]-a[0],b[1]-a[1]);seg.push(d);L+=d;}
  const scale=tr.km*1000/L;
  const xy=S.map(p=>[p[0]*scale,p[1]*scale]);
  // curvature per sample
  const curv=new Float64Array(N);
  for(let i=0;i<N;i++){
    const a=xy[(i-1+N)%N],b=xy[i],c=xy[(i+1)%N];
    const abx=b[0]-a[0],aby=b[1]-a[1],bcx=c[0]-b[0],bcy=c[1]-b[1];
    const cross=abx*bcy-aby*bcx, la=Math.hypot(abx,aby),lb=Math.hypot(bcx,bcy);
    curv[i]=Math.abs(cross)/(la*lb*Math.max((la+lb)/2,1e-6));
  }
  // smooth curvature
  const cs=new Float64Array(N);
  for(let i=0;i<N;i++){let s=0;for(let k2=-3;k2<=3;k2++)s+=curv[(i+k2+N)%N];cs[i]=s/7;}
  // speed profile: vmax = min(vtop, sqrt(aLat/k)), then fwd/back accel limits
  const vtop=92,aLat=34,aAcc=12,aBrk=42;
  let v=new Float64Array(N);
  for(let i=0;i<N;i++)v[i]=Math.min(vtop,Math.sqrt(aLat/Math.max(cs[i],1e-5)));
  for(let pass=0;pass<3;pass++){
    for(let i=0;i<N*2;i++){const j=i%N,k2=(j+1)%N;const ds=seg[j]*scale;
      v[k2]=Math.min(v[k2],Math.sqrt(v[j]*v[j]+2*aAcc*ds));}
    for(let i=N*2;i>=0;i--){const j=i%N,k2=(j-1+N)%N;const ds=seg[k2]*scale;
      v[k2]=Math.min(v[k2],Math.sqrt(v[j]*v[j]+2*aBrk*ds));}
  }
  const arc=new Float64Array(N);let acc=0;
  for(let i=0;i<N;i++){arc[i]=acc/(L*scale);acc+=seg[i]*scale;}
  // arc-correct index lookup: fraction of ARC -> sample index (GPS points are corner-dense)
  const LUT=new Uint16Array(2048);
  {let j=0;
   for(let k=0;k<2048;k++){const f=k/2048;
     while(j<N-1&&arc[j+1]<=f)j++;
     LUT[k]=j;}}
  // base lap time, calibrated to the real circuit's pace
  let lapT=0;for(let i=0;i<N;i++)lapT+=seg[i]*scale/v[i];
  const cal=lapT/(tr.targetLap||lapT);
  for(let i=0;i<N;i++)v[i]*=cal;
  lapT=tr.targetLap||lapT;
  return {...tr,xy,curv:cs,v,arc,LUT,N,len:L*scale,baseLap:lapT,
          pitEntry:0.965,pitExit:0.045,sectors:[0.33,0.66]};
}

